'use strict';
/*
 * Lights Qout: a quantum Lights Out.
 *
 * Every cell is a qubit restricted to the four states |0⟩ |1⟩ |+⟩ |−⟩
 * (encoded 0..3). X and Z presses act on a cell and its four neighbours, H
 * on a single cell. Puzzles are generated by scrambling the solved board with
 * a seeded RNG, so each one is solvable within its par.
 */
(() => {
  const GAME_ID = 'lights-qout';
  const rec = (k, v, m) => (window.QR ? QR.set(GAME_ID, k, v, m) : false);
  const t = (s, v) => (window.QA ? QA.t(s, v) : String(s).replace(/\{(\w+)\}/g, (m, k) => (v && k in v ? v[k] : m)));

  const GATES = {
    X: [1, 0, 2, 3], // |0⟩↔|1⟩, |±⟩ unchanged (up to global phase)
    Z: [0, 1, 3, 2], // |+⟩↔|−⟩, |0⟩/|1⟩ unchanged
    H: [2, 3, 0, 1], // |0⟩↔|+⟩, |1⟩↔|−⟩
  };
  const KETS = ['|0⟩', '|1⟩', '|+⟩', '|−⟩'];
  // Bloch vectors projected onto the XZ plane (x right, z up).
  const VEC = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  const STATE_COLORS = ['#e8e5ff', '#ffe14d', '#3ff4ff', '#ff4fd8'];
  const TOOL_COLORS = { X: '#ffe14d', Z: '#ff4fd8', H: '#3ff4ff' };

  // size, X presses, H gates, Z presses, holes, locked cells
  const LEVELS = [
    { n: 3, x: 1, h: 0, z: 0 },
    { n: 3, x: 2, h: 0, z: 0 },
    { n: 3, x: 0, h: 1, z: 0 },
    { n: 3, x: 1, h: 1, z: 0 },
    { n: 3, x: 0, h: 1, z: 1 },
    { n: 4, x: 3, h: 0, z: 0 },
    { n: 4, x: 2, h: 2, z: 1 },
    { n: 4, x: 3, h: 2, z: 2 },
    { n: 4, x: 2, h: 3, z: 2, holes: 1 },
    { n: 5, x: 4, h: 2, z: 1 },
    { n: 5, x: 4, h: 3, z: 2 },
    { n: 5, x: 5, h: 3, z: 3, locked: 2 },
    { n: 5, x: 5, h: 4, z: 3, holes: 2 },
    { n: 5, x: 6, h: 4, z: 4, locked: 3 },
    { n: 6, x: 6, h: 4, z: 3 },
    { n: 6, x: 7, h: 5, z: 4, locked: 3, holes: 2 },
  ];
  const RANDOM = LEVELS.length;

  function mulberry(seed) {
    return () => {
      seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // ------------------------------------------------------------ puzzle --
  function makeBoard(n, holes, locked) {
    const cross = [];
    for (let i = 0; i < n * n; i++) {
      const r = Math.floor(i / n), c = i % n, out = [i];
      if (c > 0) out.push(i - 1);
      if (c < n - 1) out.push(i + 1);
      if (r > 0) out.push(i - n);
      if (r < n - 1) out.push(i + n);
      cross.push(out.filter(j => !holes.has(j)));
    }
    return { n, holes, locked, cross };
  }

  function applyGate(board, state, tool, i) {
    const map = GATES[tool];
    const cells = tool === 'H' ? [i] : board.cross[i];
    for (const j of cells) state[j] = map[state[j]];
    return cells;
  }

  const solved = (board, state) => state.every((s, i) => board.holes.has(i) || s === 0);

  function generate(spec, seed) {
    for (let attempt = 0; attempt < 200; attempt++) {
      const rng = mulberry(seed * 977 + attempt);
      const n = spec.n, all = [...Array(n * n).keys()];
      const pick = (list, k) => {
        const a = [...list], out = [];
        while (out.length < k && a.length) out.push(a.splice(Math.floor(rng() * a.length), 1)[0]);
        return out;
      };
      const holes = new Set(pick(all, spec.holes || 0));
      const valid = all.filter(i => !holes.has(i));
      const locked = new Set(pick(valid, spec.locked || 0));
      const board = makeBoard(n, holes, locked);
      const pressable = valid.filter(i => !locked.has(i));
      const state = Array(n * n).fill(0);
      const xs = pick(pressable, spec.x);
      for (const i of xs) applyGate(board, state, 'X', i);
      const hs = pick(pressable, spec.h);
      for (const i of hs) applyGate(board, state, 'H', i);
      const hset = new Set(hs);
      const zc = pressable.filter(i => board.cross[i].some(j => hset.has(j)));
      const zs = pick(zc, spec.z);
      for (const i of zs) applyGate(board, state, 'Z', i);
      if (solved(board, state)) continue;
      if (zs.length < spec.z) continue;
      return { board, start: state, par: xs.length + hs.length + zs.length, hBudget: hs.length };
    }
    throw new Error('could not generate puzzle');
  }

  // ------------------------------------------------------------ canvas --
  const W = 520, H = 520;
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const DPR = (window.devicePixelRatio || 1) > 1 ? 2 : 1;
  canvas.width = W * DPR;
  canvas.height = H * DPR;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

  // ------------------------------------------------------------- audio --
  let actx = null, muted = false;
  function audio() {
    if (!actx) {
      try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { actx = null; }
    }
    if (actx && actx.state === 'suspended') actx.resume();
    return actx;
  }
  function tone(f, dur, type = 'square', vol = 0.035, f2 = null, delay = 0) {
    if (muted) return;
    const a = audio();
    if (!a) return;
    const t0 = a.currentTime + delay;
    const o = a.createOscillator(), g = a.createGain();
    o.type = type;
    o.frequency.setValueAtTime(f, t0);
    if (f2) o.frequency.exponentialRampToValueAtTime(f2, t0 + dur);
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g).connect(a.destination);
    o.start(t0);
    o.stop(t0 + dur + 0.02);
  }
  const sfx = {
    X() { tone(330, 0.12, 'triangle', 0.05, 660); },
    Z() { tone(700, 0.14, 'sawtooth', 0.025, 350); },
    H() { tone(500, 0.16, 'sine', 0.05, 1000); },
    nope() { tone(140, 0.12, 'square', 0.04, 90); },
    undo() { tone(500, 0.06, 'triangle', 0.03, 300); },
    win() { [523, 659, 784, 1046, 1318].forEach((f, i) => tone(f, 0.15, 'triangle', 0.05, null, i * 0.09)); },
  };

  // ------------------------------------------------------------- state --
  let levelIdx = 0, puzzle, state, moves = 0, hLeft = 0, history = [];
  let tool = 'X', hover = -1, time = 0, won = false, randomSeed = 1;
  const anims = new Map(), ripples = [];
  let progress = {};
  try { progress = JSON.parse(localStorage.getItem('lightsqout-progress') || '{}') || {}; } catch (e) { progress = {}; }
  try { levelIdx = Math.min(RANDOM, Math.max(0, +localStorage.getItem('lightsqout-level') || 0)); } catch (e) { levelIdx = 0; }

  function saveProgress() {
    try {
      localStorage.setItem('lightsqout-progress', JSON.stringify(progress));
      localStorage.setItem('lightsqout-level', String(levelIdx));
    } catch (e) { /* storage unavailable */ }
  }

  function randomSpec(rng) {
    const n = rng() < 0.5 ? 5 : 6;
    return { n, x: 4 + Math.floor(rng() * 4), h: 2 + Math.floor(rng() * 4), z: 1 + Math.floor(rng() * 4), holes: Math.floor(rng() * 3), locked: Math.floor(rng() * 4) };
  }

  function loadLevel(i, freshRandom = true) {
    levelIdx = i;
    if (i === RANDOM) {
      if (freshRandom) randomSeed = Math.floor(Math.random() * 1e9);
      puzzle = generate(randomSpec(mulberry(randomSeed)), randomSeed);
    } else {
      puzzle = generate(LEVELS[i], 1000 + i);
    }
    state = [...puzzle.start];
    moves = 0; hLeft = puzzle.hBudget; history = []; won = false;
    anims.clear(); ripples.length = 0;
    showOverlay(null);
    setStatus(i === RANDOM ? 'Random puzzle. Bring every qubit to |0⟩.' : introFor(i));
    saveProgress();
  }

  function introFor(i) {
    return [
      'Classic Lights Out: an X press flips a cell and its neighbours. Get every arrow pointing up.',
      'Two lights this time. X presses that overlap cancel out.',
      'This qubit is in |+⟩. X presses do nothing to it. Use the H gate.',
      'Mix it up: one X puzzle and one H.',
      'This one is |−⟩. Either fix its phase with a Z press first, or apply H and then fix the bit.',
      'A 4×4 grid. Pure Lights Out.',
      'Two superposed qubits. Each one needs exactly one H.',
      'Phases and bits together. Plan which basis to solve each cell in.',
      'There\'s a hole in the board. Presses don\'t reach through it.',
      'A 5×5 grid.',
      'More qubits in the X basis.',
      '🔒 Locked cells can\'t be pressed, but presses next to them still reach them.',
      'A board with holes.',
      'Several locked cells.',
      '6×6.',
      'The final puzzle: everything at once.',
    ][i] || 'Bring every qubit to |0⟩.';
  }

  function act(i) {
    if (won || i < 0 || puzzle.board.holes.has(i)) return;
    audio();
    if (puzzle.board.locked.has(i)) { setStatus('🔒 Locked: this cell can\'t be pressed, but its neighbours\' presses still reach it.'); sfx.nope(); return; }
    if (tool === 'H' && hLeft <= 0) { setStatus('No H gates left. Undo (U) or reset (R).'); sfx.nope(); return; }
    history.push({ state: [...state], moves, hLeft });
    const before = [...state];
    const cells = applyGate(puzzle.board, state, tool, i);
    for (const j of cells) if (before[j] !== state[j]) anims.set(j, { from: before[j], to: state[j], t: 0 });
    ripples.push({ i, t: 0, color: TOOL_COLORS[tool], cross: tool !== 'H' });
    moves++;
    if (tool === 'H') hLeft--;
    sfx[tool]();
    const changed = cells.filter(j => before[j] !== state[j]).length;
    if (!changed) setStatus('{gate} did nothing here: those qubits are its eigenstates.', '', { gate: tool });
    else setStatus(' ');
    if (solved(puzzle.board, state)) win();
  }

  function undo() {
    if (!history.length || won) return;
    const h = history.pop();
    for (let j = 0; j < state.length; j++) if (state[j] !== h.state[j]) anims.set(j, { from: state[j], to: h.state[j], t: 0 });
    state = h.state; moves = h.moves; hLeft = h.hLeft;
    sfx.undo();
  }

  function win() {
    won = true;
    const par = puzzle.par;
    const stars = moves <= par ? 3 : moves <= par + 3 ? 2 : 1;
    if (levelIdx !== RANDOM) {
      const prev = progress[levelIdx];
      if (!prev || stars > prev.stars || (stars === prev.stars && moves < prev.moves)) progress[levelIdx] = { stars, moves };
      saveProgress();
      const done = Object.values(progress);
      rec('stars', done.reduce((s, p) => s + p.stars, 0), 'max');
      rec('solved', done.length, 'max');
    } else rec('randomSolved', 1, 'add');
    sfx.win();
    setStatus(moves < par ? 'Under par, nice! {moves} moves (par {par}).' : 'Solved in {moves} moves (par {par}).', 'win', { moves, par });
    setTimeout(() => { if (won) showOverlay('win', { stars, moves, par }); }, 700);
  }

  // ------------------------------------------------------------ layout --
  function geom() {
    const n = puzzle.board.n;
    const cs = Math.min(92, Math.floor(470 / n));
    const size = cs * n;
    return { n, cs, ox: (W - size) / 2, oy: (H - size) / 2 };
  }
  function cellAt(x, y) {
    const { n, cs, ox, oy } = geom();
    const c = Math.floor((x - ox) / cs), r = Math.floor((y - oy) / cs);
    if (c < 0 || c >= n || r < 0 || r >= n) return -1;
    return r * n + c;
  }

  // ------------------------------------------------------------ render --
  function rrect(x, y, w, h, r) {
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x, y, w, h, r); else ctx.rect(x, y, w, h);
  }

  // Arrow tip during an animation: a π rotation about an in-plane axis
  // projects onto a straight line through the midpoint of the two endpoints.
  function tipOf(i) {
    const a = anims.get(i);
    if (!a) return VEC[state[i]];
    const k = Math.min(1, a.t / 0.38);
    const c = Math.cos(Math.PI * k);
    const [x0, z0] = VEC[a.from], [x1, z1] = VEC[a.to];
    const mx = (x0 + x1) / 2, mz = (z0 + z1) / 2;
    return [mx + c * (x0 - mx), mz + c * (z0 - mz)];
  }

  function render() {
    ctx.fillStyle = '#04030c';
    ctx.fillRect(0, 0, W, H);
    const { n, cs, ox, oy } = geom();
    const B = puzzle.board;
    const preview = new Set();
    if (hover >= 0 && !won && !B.holes.has(hover) && !B.locked.has(hover)) {
      for (const j of tool === 'H' ? [hover] : B.cross[hover]) preview.add(j);
    }

    for (let i = 0; i < n * n; i++) {
      if (B.holes.has(i)) continue;
      const x = ox + (i % n) * cs, y = oy + Math.floor(i / n) * cs;
      const pad = Math.max(3, cs * 0.06), w = cs - pad * 2;
      const s = state[i];
      const lit = s === 1;
      ctx.fillStyle = lit ? '#2a2208' : s >= 2 ? '#0b1630' : '#0c0a26';
      rrect(x + pad, y + pad, w, w, cs * 0.14); ctx.fill();
      ctx.strokeStyle = preview.has(i) ? TOOL_COLORS[tool] : '#262058';
      ctx.lineWidth = preview.has(i) ? 2.2 : 1.2;
      rrect(x + pad + 0.5, y + pad + 0.5, w - 1, w - 1, cs * 0.14); ctx.stroke();
      if (lit) {
        ctx.save();
        ctx.shadowColor = '#ffe14d'; ctx.shadowBlur = 18;
        ctx.strokeStyle = 'rgba(255,225,77,.5)';
        rrect(x + pad + 0.5, y + pad + 0.5, w - 1, w - 1, cs * 0.14); ctx.stroke();
        ctx.restore();
      }

      // Bloch dial.
      const cx = x + cs / 2, cy = y + cs / 2, R = cs * 0.3;
      ctx.strokeStyle = 'rgba(150,144,198,.35)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(cx, cy, R, R * 0.28, 0, 0, Math.PI * 2); ctx.stroke();
      const [tx, tz] = tipOf(i);
      const color = STATE_COLORS[anims.has(i) ? anims.get(i).to : s];
      const ex = cx + tx * R, ey = cy - tz * R;
      ctx.save();
      ctx.strokeStyle = color; ctx.fillStyle = color;
      ctx.shadowColor = color; ctx.shadowBlur = s === 0 && !anims.has(i) ? 0 : 10;
      ctx.lineWidth = Math.max(2, cs * 0.05);
      ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();
      const len = Math.hypot(tx, tz);
      ctx.beginPath(); ctx.arc(ex, ey, Math.max(2.5, cs * 0.055) * (0.6 + 0.4 * len), 0, Math.PI * 2); ctx.fill();
      ctx.restore();

      ctx.fillStyle = s === 0 ? '#6f69a3' : color;
      ctx.font = `bold ${Math.max(9, Math.round(cs * 0.15))}px "JetBrains Mono", monospace`;
      ctx.textAlign = 'right'; ctx.textBaseline = 'bottom';
      ctx.fillText(KETS[s], x + cs - pad - 4, y + cs - pad - 2);
      if (B.locked.has(i)) {
        ctx.font = `${Math.max(10, Math.round(cs * 0.16))}px sans-serif`;
        ctx.textAlign = 'left'; ctx.textBaseline = 'top';
        ctx.fillText('🔒', x + pad + 4, y + pad + 3);
      }
    }

    for (const r of ripples) {
      const k = r.t / 0.5;
      const x = ox + (r.i % n) * cs + cs / 2, y = oy + Math.floor(r.i / n) * cs + cs / 2;
      ctx.save();
      ctx.globalAlpha = Math.max(0, 1 - k);
      ctx.strokeStyle = r.color; ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.arc(x, y, cs * (0.3 + k * (r.cross ? 1.2 : 0.5)), 0, Math.PI * 2); ctx.stroke();
      ctx.restore();
    }
  }

  // --------------------------------------------------------------- HUD --
  const $ = id => document.getElementById(id);
  const statusEl = $('status');
  // The status is kept as key + values so a language switch can redraw it.
  let lastStatus = { key: '', cls: '', vars: null };
  function setStatus(key, cls = '', vars = null) {
    lastStatus = { key, cls, vars };
    statusEl.textContent = t(key, vars);
    statusEl.className = 'status' + (cls ? ' ' + cls : '');
  }
  const set = (node, v) => { v = String(v); if (node._v !== v) { node._v = v; node.textContent = v; } };
  function updateHUD() {
    set($('level'), levelIdx === RANDOM ? '∞' : levelIdx + 1);
    set($('moves'), moves);
    set($('par'), puzzle.par);
    set($('hleft'), hLeft);
    document.querySelectorAll('#tools button').forEach(b => {
      b.classList.toggle('on', b.dataset.tool === tool);
      if (b.dataset.tool === 'H') b.disabled = hLeft <= 0 && !won;
    });
    $('undoBtn').disabled = !history.length || won;
    $('prevBtn').disabled = levelIdx === 0;
  }

  // ----------------------------------------------------------- overlay --
  const overlay = $('overlay');
  let overlayState = null;
  function showOverlay(kind, info) {
    overlayState = kind ? { kind, info } : null;
    if (!kind) { overlay.classList.remove('show'); overlay.innerHTML = ''; return; }
    let html = '';
    if (kind === 'win') {
      const stars = '★'.repeat(info.stars) + '☆'.repeat(3 - info.stars);
      html = `<div class="card">
        <div class="big">|ψ⟩ = |00…0⟩</div>
        <div class="bigstars">${stars}</div>
        <p>${t(info.stars < 3 ? '{moves} moves · par {par}. Three stars needs {par} moves or fewer.' : '{moves} moves · par {par}.', { moves: info.moves, par: info.par })}</p>
        <div class="row">
          <button class="go" type="button" data-act="next">${t(levelIdx >= RANDOM - 1 ? 'RANDOM PUZZLE' : 'NEXT LEVEL')}</button>
        </div>
        <div class="row">
          <button class="ghostbtn" type="button" data-act="retry">${t('RETRY')}</button>
          <button class="ghostbtn" type="button" data-act="levels">${t('LEVELS')}</button>
        </div>
      </div>`;
    } else if (kind === 'levels') {
      const btns = LEVELS.map((L, i) => {
        const p = progress[i];
        const stars = p ? '★'.repeat(p.stars) + '☆'.repeat(3 - p.stars) : '';
        return `<button type="button" data-level="${i}" class="${i === levelIdx ? 'cur' : ''}">${i + 1}<span class="stars">${stars}</span></button>`;
      }).join('');
      const total = Object.values(progress).reduce((s, p) => s + p.stars, 0);
      html = `<div class="card">
        <div class="big">${t('LEVELS')}</div>
        <p>${t('{total} / {max} stars', { total, max: LEVELS.length * 3 })}</p>
        <div class="levels">${btns}</div>
        <div class="row">
          <button class="go" type="button" data-level="${RANDOM}">${t('∞ RANDOM')}</button>
          <button class="ghostbtn" type="button" data-act="close">${t('CLOSE')}</button>
        </div>
      </div>`;
    }
    overlay.innerHTML = html;
    overlay.classList.add('show');
  }

  overlay.addEventListener('click', e => {
    const lv = e.target.closest('[data-level]');
    if (lv) { loadLevel(+lv.dataset.level); return; }
    const b = e.target.closest('[data-act]');
    if (!b) { if (!won) showOverlay(null); return; }
    switch (b.dataset.act) {
      case 'next': loadLevel(Math.min(RANDOM, levelIdx + 1)); break;
      case 'retry': loadLevel(levelIdx, false); break;
      case 'levels': showOverlay('levels'); break;
      case 'close': showOverlay(null); break;
    }
  });

  // ------------------------------------------------------------- input --
  const toBoard = e => {
    const r = canvas.getBoundingClientRect();
    return [(e.clientX - r.left) / r.width * W, (e.clientY - r.top) / r.height * H];
  };
  canvas.addEventListener('pointermove', e => { hover = cellAt(...toBoard(e)); });
  canvas.addEventListener('pointerleave', () => { hover = -1; });
  canvas.addEventListener('click', e => act(cellAt(...toBoard(e))));
  $('tools').addEventListener('click', e => {
    const b = e.target.closest('[data-tool]');
    if (b) tool = b.dataset.tool;
  });
  $('undoBtn').addEventListener('click', undo);
  $('resetBtn').addEventListener('click', () => loadLevel(levelIdx, false));
  $('levelsBtn').addEventListener('click', () => showOverlay('levels'));
  $('prevBtn').addEventListener('click', () => { if (levelIdx > 0) loadLevel(levelIdx - 1); });
  $('nextBtn').addEventListener('click', () => loadLevel(Math.min(RANDOM, levelIdx + 1)));

  const muteBtn = $('muteBtn');
  function toggleMute() {
    muted = !muted;
    muteBtn.textContent = t(muted ? '♪ OFF' : '♪ ON');
    try { localStorage.setItem('lightsqout-muted', muted ? '1' : '0'); } catch (e) { /* ignore */ }
  }
  muteBtn.textContent = t('♪ ON');
  try { if (localStorage.getItem('lightsqout-muted') === '1') toggleMute(); } catch (e) { /* ignore */ }
  muteBtn.addEventListener('click', () => { toggleMute(); muteBtn.blur(); });

  window.addEventListener('keydown', e => {
    if (e.ctrlKey || e.metaKey || e.altKey) {
      if ((e.ctrlKey || e.metaKey) && e.code === 'KeyZ') { e.preventDefault(); undo(); }
      return;
    }
    switch (e.code) {
      case 'KeyX': case 'Digit1': tool = 'X'; break;
      case 'KeyZ': case 'Digit2': tool = 'Z'; break;
      case 'KeyH': case 'Digit3': tool = 'H'; break;
      case 'KeyU': case 'Backspace': undo(); break;
      case 'KeyR': loadLevel(levelIdx, false); break;
      case 'KeyN': loadLevel(Math.min(RANDOM, levelIdx + 1)); break;
      case 'KeyP': if (levelIdx > 0) loadLevel(levelIdx - 1); break;
      case 'KeyL': showOverlay('levels'); break;
      case 'Escape': showOverlay(null); break;
      case 'KeyM': toggleMute(); break;
    }
  });

  if (window.QA) {
    QA.onChange(() => {
      setStatus(lastStatus.key, lastStatus.cls, lastStatus.vars);
      if (overlayState) showOverlay(overlayState.kind, overlayState.info);
      muteBtn.textContent = t(muted ? '♪ OFF' : '♪ ON');
    });
  }

  // -------------------------------------------------------------- loop --
  loadLevel(levelIdx);
  let last = performance.now();
  function frame(now) {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    time += dt;
    for (const [i, a] of anims) if ((a.t += dt) > 0.38) anims.delete(i);
    for (let k = ripples.length - 1; k >= 0; k--) if ((ripples[k].t += dt) > 0.5) ripples.splice(k, 1);
    render();
    updateHUD();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
